const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),request=require('supertest');
const {createAuthenticatedActionApp}=require('./authenticated-app.cjs');
let directory,app,alice,bob;const data={tagline:'一句话介绍',about:'我的方法介绍',focus:'目前关注',visibility:'private'};
beforeEach(async()=>{directory=fs.mkdtempSync(path.join(os.tmpdir(),'dianliang-profile-'));app=createAuthenticatedActionApp({dataDir:directory,reviewDirectory:path.join(directory,'assets'),rateLimitEnabled:false}).app;alice=request.agent(app);bob=request.agent(app);await alice.post('/api/register').send({name:'profile-alice',password:'test-only-2026'});await bob.post('/api/register').send({name:'profile-bob',password:'test-only-2026'})});
afterEach(()=>{if(!path.resolve(directory).startsWith(path.resolve(os.tmpdir())+path.sep))throw Error('Unexpected fixture');fs.rmSync(directory,{recursive:true,force:true})});
it('shows an author introduction to peers only after explicit publishing and hides it again after withdrawal',async()=>{
 const initial=(await alice.get('/api/review-own-profile')).body,target={treeId:'dianliang-review-catalog-v1',nodeId:'od-eq'};await alice.post('/api/records').send({...target,text:'已完成检验',lightUp:true,visibility:'private'});expect((await alice.post('/api/tutorials').send({...target,title:'公开作者的一份方法',method:'先求解再检验',visibility:'public'})).status).toBe(201);const read=()=>bob.get('/api/review-public-tutorials/author').query({id:initial.ownerId});const privateSave=await alice.post('/api/review-own-profile').set('If-Match',initial.revision).send(data);expect(privateSave.status).toBe(200);expect((await read()).body.author.profile).toBeNull();const published=await alice.post('/api/review-own-profile').set('If-Match',privateSave.body.revision).send({...data,visibility:'public',consent:true});expect(published.status).toBe(200);expect((await read()).body.author.profile).toEqual({tagline:data.tagline,about:data.about,focus:data.focus});const withdrawn=await alice.post('/api/review-own-profile').set('If-Match',published.body.revision).send({...data,withdrawConsent:true});expect(withdrawn.status).toBe(200);expect((await read()).body.author.profile).toBeNull();expect((await alice.get('/api/review-own-profile')).body.profile.about).toBe(data.about);expect((await read()).body.total).toBe(1);
});
it('saves only the current owner profile and keeps retry stable after a lost acknowledgement',async()=>{
 const first=(await alice.get('/api/review-own-profile')).body;expect(first.profile).toBeNull();const saved=await alice.post('/api/review-own-profile').set('If-Match',first.revision).send(data);expect(saved.status).toBe(200);expect(saved.body.ownerId).toBe(first.ownerId);const file=path.join(directory,'profiles.json'),bytes=fs.readFileSync(file,'utf8');const repeat=await alice.post('/api/review-own-profile').set('If-Match',first.revision).send(data);expect(repeat.body.repeated).toBe(true);expect(repeat.body.revision).toBe(saved.body.revision);expect(fs.readFileSync(file,'utf8')).toBe(bytes);expect((await bob.get('/api/review-own-profile')).body.profile).toBeNull();expect((await alice.get('/api/review-account-export')).body.service.profile.about).toBe(data.about);
});
it('requires explicit public and withdrawal choices while preventing stale replacement',async()=>{
 const first=(await alice.get('/api/review-own-profile')).body,body={...data,visibility:'public'};expect((await alice.post('/api/review-own-profile').set('If-Match',first.revision).send(body)).status).toBe(403);const publicSave=await alice.post('/api/review-own-profile').set('If-Match',first.revision).send({...body,consent:true});expect(publicSave.status).toBe(200);expect((await alice.post('/api/review-own-profile').set('If-Match',first.revision).send({...body,about:'另一窗口的旧输入',consent:true})).status).toBe(409);expect((await alice.post('/api/review-own-profile').set('If-Match',publicSave.body.revision).send(data)).status).toBe(403);expect((await alice.post('/api/review-own-profile').set('If-Match',publicSave.body.revision).send({...data,withdrawConsent:true})).status).toBe(200);
});
it('enforces session actor, origin, field whitelist and bounded text',async()=>{
 const r=(await alice.get('/api/review-own-profile')).body;expect((await request(app).get('/api/review-own-profile')).status).toBe(401);expect((await bob.post('/api/review-own-profile').set('If-Match',r.revision).set('X-Action-Account',r.ownerId).send(data)).status).toBe(409);expect((await alice.post('/api/review-own-profile').set('If-Match',r.revision).set('Origin','https://not-authorized.example').send(data)).status).toBe(403);expect((await alice.post('/api/review-own-profile').send(data)).status).toBe(428);for(const input of [{...data,ownerId:r.ownerId},{...data,about:'x'.repeat(1601)}])expect((await alice.post('/api/review-own-profile').set('If-Match',r.revision).send(input)).status).toBe(400);
});
it('preserves corrupt profile storage and never exposes arbitrary profile fields',async()=>{
 const r=(await alice.get('/api/review-own-profile')).body,file=path.join(directory,'profiles.json');fs.writeFileSync(file,JSON.stringify([{id:r.ownerId,...data,secret:'PRIVATE-SECRET'}]));expect(JSON.stringify((await alice.get('/api/review-own-profile')).body)).not.toContain('PRIVATE-SECRET');fs.writeFileSync(file,'{damaged');expect((await alice.get('/api/review-own-profile')).status).toBe(503);expect((await alice.post('/api/review-own-profile').set('If-Match',r.revision).send(data)).status).toBe(503);expect(fs.readFileSync(file,'utf8')).toBe('{damaged');
});
